def holdings_change(before, after):
    old = set(before)
    new = set(after)
    added = sorted([t for t in after if t not in old])
    dropped = sorted([t for t in before if t not in new])
    return (added, dropped, len(old & new))

def holdings_change(before, after):
    old = set(before)
    new = set(after)
    added = [t for t in dict.fromkeys(after) if t not in old]
    dropped = [t for t in dict.fromkeys(before) if t not in new]
    return (added, dropped, len(old & new))

def holdings_change(before, after):
    old = set(before)
    new = set(after)
    kept = sum(1 for t in after if t in old)
    return (sorted(new - old), sorted(old - new), kept)
